const dbDir = '/home/user/project/data'
const dbPath = path.join(dbDir, 'app.sqlite')

if (!fs.existsSync(dbDir)) {
  fs.mkdirSync(dbDir, { recursive: true })
}

export const db = new Database(dbPath)

