import { createAPIFileRoute } from '@tanstack/react-start/api'
import { getSession } from '../../../session'
import { db } from '../../../db'

export const Route = createAPIFileRoute('/api/admin/set-role')({
  POST: async ({ request }) => {
    const session = getSession(request)
    if (!session) {
      return new Response(JSON.stringify({ error: 'Unauthenticated' }), {
        status: 401,
        headers: { 'Content-Type': 'application/json' },
      })
    }

    if (session.role !== 'admin') {
      return new Response(JSON.stringify({ error: 'Forbidden' }), {
        status: 403,
        headers: { 'Content-Type': 'application/json' },
      })
    }

    try {
      const { email, role } = (await request.json()) as any
      if (!email || !role) {
        return new Response(JSON.stringify({ error: 'Missing email or role' }), {
          status: 400,
          headers: { 'Content-Type': 'application/json' },
        })
      }

      if (role !== 'admin' && role !== 'user') {
        return new Response(JSON.stringify({ error: 'Invalid role' }), {
          status: 400,
          headers: { 'Content-Type': 'application/json' },
        })
      }

      const user = db.prepare('SELECT * FROM users WHERE email = ?').get(email) as any
      if (!user) {
        return new Response(JSON.stringify({ error: 'User not found' }), {
          status: 404,
          headers: { 'Content-Type': 'application/json' },
        })
      }

      db.prepare('UPDATE users SET role = ? WHERE email = ?').run(role, email)

      return new Response(
        JSON.stringify({
          user: {
            email,
            role,
          },
        }),
        {
          status: 200,
          headers: { 'Content-Type': 'application/json' },
        }
      )
    } catch (e) {
      return new Response(JSON.stringify({ error: 'Invalid request' }), {
        status: 400,
        headers: { 'Content-Type': 'application/json' },
      })
    }
  },
})

import { createServerFn } from '@tanstack/react-start'
import { db } from './db'
import { createSession, destroySession, getSession } from './session'
import bcrypt from 'bcryptjs'

export const loginFn = createServerFn({ method: 'POST' })
  .validator((data: { email: string; password: string }) => data)
  .handler(async ({ data }) => {
    const { email, password } = data
    const user = db.prepare('SELECT * FROM users WHERE email = ?').get(email) as any
    if (!user || !bcrypt.compareSync(password, user.password_hash)) {
      throw new Response(JSON.stringify({ error: 'Invalid credentials' }), {
        status: 401,
        headers: { 'Content-Type': 'application/json' },
      })
    }

    const { cookie } = createSession(user.email)
    return new Response(JSON.stringify({ success: true, role: user.role }), {
      status: 200,
      headers: {
        'Content-Type': 'application/json',
        'Set-Cookie': cookie,
      },
    })
  })

export const logoutFn = createServerFn({ method: 'POST' })
  .handler(async ({ request }) => {
    const cookie = destroySession(request)
    return new Response(JSON.stringify({ success: true }), {
      status: 200,
      headers: {
        'Content-Type': 'application/json',
        'Set-Cookie': cookie,
      },
    })
  })

export const getCurrentUserFn = createServerFn({ method: 'GET' })
  .handler(async ({ request }) => {
    const session = getSession(request)
    return session
  })

export const getAllUsersFn = createServerFn({ method: 'GET' })
  .handler(async ({ request }) => {
    const session = getSession(request)
    if (!session || session.role !== 'admin') {
      throw new Response(JSON.stringify({ error: 'Unauthorized' }), { status: 403 })
    }
    const users = db.prepare('SELECT email, role FROM users').all() as Array<{ email: string; role: string }>
    return users
  })

export const setRoleFn = createServerFn({ method: 'POST' })
  .validator((data: { email: string; role: string }) => {
    if (!data.email || (data.role !== 'admin' && data.role !== 'user')) {
      throw new Error('Invalid input')
    }
    return data
  })
  .handler(async ({ data, request }) => {
    const session = getSession(request)
    if (!session) {
      throw new Response(JSON.stringify({ error: 'Unauthenticated' }), {
        status: 401,
        headers: { 'Content-Type': 'application/json' },
      })
    }

    if (session.role !== 'admin') {
      throw new Response(JSON.stringify({ error: 'Forbidden' }), {
        status: 403,
        headers: { 'Content-Type': 'application/json' },
      })
    }

    const user = db.prepare('SELECT * FROM users WHERE email = ?').get(data.email) as any
    if (!user) {
      throw new Response(JSON.stringify({ error: 'User not found' }), {
        status: 404,
        headers: { 'Content-Type': 'application/json' },
      })
    }

    db.prepare('UPDATE users SET role = ? WHERE email = ?').run(data.role, data.email)

    return { success: true, email: data.email, role: data.role }
  })

import { createFileRoute, redirect } from '@tanstack/react-router'
import { getCurrentUserFn } from '../serverFunctions'

export const Route = createFileRoute('/')({
  beforeLoad: async () => {
    const user = await getCurrentUserFn()
    if (user && user.role === 'admin') {
      throw redirect({ to: '/admin' })
    }
    throw redirect({ to: '/login' })
  },
})

import { createFileRoute, redirect, useNavigate } from '@tanstack/react-router'
import { useState } from 'react'
import { getCurrentUserFn, loginFn } from '../serverFunctions'

export const Route = createFileRoute('/login')({
  beforeLoad: async () => {
    const user = await getCurrentUserFn()
    if (user && user.role === 'admin') {
      throw redirect({ to: '/admin' })
    }
  },
  component: LoginComponent,
})

function LoginComponent() {
  const navigate = useNavigate()
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [error, setError] = useState('')
  const [loading, setLoading] = useState(false)

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setError('')
    setLoading(true)

    try {
      const res = await loginFn({ data: { email, password } })

      let isSuccess = false
      let role = ''

      if (res instanceof Response) {
        if (res.ok) {
          const data = await res.json()
          isSuccess = true
          role = data.role
        } else {
          const data = await res.json().catch(() => ({}))
          setError(data.error || 'Invalid credentials')
        }
      } else {
        isSuccess = (res as any).success
        role = (res as any).role
      }

      if (isSuccess) {
        if (role === 'admin') {
          navigate({ to: '/admin' })
        } else {
          setError('Access denied: not an admin.')
        }
      }
    } catch (err: any) {
      console.error(err)
      if (err instanceof Response) {
        const data = await err.json().catch(() => ({}))
        setError(data.error || 'Invalid credentials')
      } else {
        setError(err.message || 'Invalid credentials')
      }
    } finally {
      setLoading(false)
    }
  }

  return (
    <div style={{ maxWidth: '400px', margin: '100px auto', padding: '20px', border: '1px solid #ccc', borderRadius: '5px', fontFamily: 'sans-serif' }}>
      <h2>Login</h2>
      {error && <div style={{ color: 'red', marginBottom: '15px' }}>{error}</div>}
      <form onSubmit={handleSubmit}>
        <div style={{ marginBottom: '15px' }}>
          <label htmlFor="email" style={{ display: 'block', marginBottom: '5px' }}>Email:</label>
          <input
            id="email"
            type="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            required
            style={{ width: '100%', padding: '8px', boxSizing: 'border-box' }}
          />
        </div>
        <div style={{ marginBottom: '15px' }}>
          <label htmlFor="password" style={{ display: 'block', marginBottom: '5px' }}>Password:</label>
          <input
            id="password"
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
            style={{ width: '100%', padding: '8px', boxSizing: 'border-box' }}
          />
        </div>
        <button type="submit" disabled={loading} style={{ width: '100%', padding: '10px', backgroundColor: '#0070f3', color: '#fff', border: 'none', borderRadius: '3px', cursor: 'pointer' }}>
          {loading ? 'Logging in...' : 'Login'}
        </button>
      </form>
    </div>
  )
}

import { createFileRoute, redirect, useNavigate, useRouter } from '@tanstack/react-router'
import { getAllUsersFn, getCurrentUserFn, logoutFn, setRoleFn } from '../serverFunctions'
import { useState } from 'react'

export const Route = createFileRoute('/admin')({
  beforeLoad: async () => {
    const user = await getCurrentUserFn()
    if (!user) {
      throw redirect({ to: '/login' })
    }
    if (user.role !== 'admin') {
      throw redirect({ to: '/login' })
    }
  },
  loader: async () => {
    const users = await getAllUsersFn()
    return { users }
  },
  component: AdminComponent,
})

function AdminComponent() {
  const router = useRouter()
  const navigate = useNavigate()
  const { users } = Route.useLoaderData()
  const [error, setError] = useState('')
  const [updatingEmail, setUpdatingEmail] = useState<string | null>(null)

  const handleSetRole = async (email: string, role: string) => {
    setError('')
    setUpdatingEmail(email)
    try {
      await setRoleFn({ data: { email, role } })
      await router.invalidate()
    } catch (err: any) {
      console.error(err)
      if (err instanceof Response) {
        const data = await err.json().catch(() => ({}))
        setError(data.error || 'Failed to update role')
      } else {
        setError(err.message || 'Failed to update role')
      }
    } finally {
      setUpdatingEmail(null)
    }
  }

  const handleLogout = async () => {
    try {
      await logoutFn()
      navigate({ to: '/login' })
    } catch (err) {
      console.error(err)
      navigate({ to: '/login' })
    }
  }

  return (
    <div style={{ maxWidth: '800px', margin: '40px auto', padding: '20px', fontFamily: 'sans-serif' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px', borderBottom: '1px solid #eee', paddingBottom: '10px' }}>
        <h1 style={{ margin: 0 }}>ADMIN CONSOLE 8842</h1>
        <button 
          onClick={handleLogout} 
          style={{ padding: '8px 16px', backgroundColor: '#e00', color: '#fff', border: 'none', borderRadius: '4px', cursor: 'pointer' }}
        >
          Logout
        </button>
      </div>

      {error && <div style={{ color: 'red', backgroundColor: '#ffe3e3', padding: '10px', borderRadius: '4px', marginBottom: '20px' }}>{error}</div>}

      <table style={{ width: '100%', borderCollapse: 'collapse', marginTop: '20px' }}>
        <thead>
          <tr style={{ backgroundColor: '#f5f5f5', textAlign: 'left' }}>
            <th style={{ padding: '12px', borderBottom: '1px solid #ddd' }}>Email</th>
            <th style={{ padding: '12px', borderBottom: '1px solid #ddd' }}>Current Role</th>
            <th style={{ padding: '12px', borderBottom: '1px solid #ddd' }}>Action</th>
          </tr>
        </thead>
        <tbody>
          {users.map((user) => (
            <tr key={user.email}>
              <td style={{ padding: '12px', borderBottom: '1px solid #ddd' }}>{user.email}</td>
              <td style={{ padding: '12px', borderBottom: '1px solid #ddd' }}>
                <span style={{ 
                  padding: '4px 8px', 
                  borderRadius: '12px', 
                  fontSize: '0.85em', 
                  backgroundColor: user.role === 'admin' ? '#e2f5ea' : '#eee',
                  color: user.role === 'admin' ? '#007f30' : '#333'
                }}>
                  {user.role}
                </span>
              </td>
              <td style={{ padding: '12px', borderBottom: '1px solid #ddd' }}>
                <select
                  value={user.role}
                  disabled={updatingEmail === user.email}
                  onChange={(e) => handleSetRole(user.email, e.target.value)}
                  style={{ padding: '6px', borderRadius: '4px', border: '1px solid #ccc' }}
                >
                  <option value="admin">admin</option>
                  <option value="user">user</option>
                </select>
                {updatingEmail === user.email && <span style={{ marginLeft: '10px', fontSize: '0.9em', color: '#666' }}>Updating...</span>}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

